def build_fewshot_prompt(examples, new_input):
    lines = ["Rewrite each product description in an enthusiastic, exclamation-heavy marketing voice.\n"]
    for original, rewritten in examples:
        lines.append(f"Original: {original}\nRewritten: {rewritten}\n")
    lines.append(f"Original: {new_input}\nRewritten:")
    return "\n".join(lines)

examples = [
    ("A basic ceramic mug.", "This isn't just a mug -- it's your new morning ritual, elevated!"),
    ("A simple cotton t-shirt.", "Comfort has never looked this good -- meet your new everyday favorite!"),
]

print(build_fewshot_prompt(examples, "A small notebook."))

import json

def get_structured_response(prompt, client, max_retries=2):
    messages = [{"role": "user", "content": prompt}]
    for attempt in range(max_retries + 1):
        response = client.chat.completions.create(
            model="gpt-4.1",
            messages=messages,
            response_format={"type": "json_object"},   # constrained decoding, not just an instruction
        )
        raw = response.choices[0].message.content
        try:
            return json.loads(raw)
        except json.JSONDecodeError as e:
            if attempt == max_retries:
                raise ValueError(f"Failed to get valid JSON after {max_retries + 1} attempts") from e
            messages.append({"role": "assistant", "content": raw})
            messages.append({"role": "user", "content": f"That was not valid JSON ({e}). Return only valid JSON, nothing else."})

