def answer_question(question, index, generation_model, top_k=4):
    query_vector = embed(question)
    retrieved = index.search(query_vector, top_k=top_k)
    context_text = "\n\n".join(chunk.text for chunk in retrieved)

    prompt = (
        "Answer the question using ONLY the context below. If the answer is "
        "not present, say you don't know.\n\n"
        f"Context:\n{context_text}\n\nQuestion: {question}"
    )

    return generation_model.generate(prompt)

