def choose_approach(problem):
    if problem["knowledge_changes_frequently"] or problem["needs_source_citation"]:
        return "rag"
    if problem["needs_consistent_narrow_behavior_at_scale"] and problem["has_large_labeled_dataset"]:
        return "fine-tuning"   # but try prompting first regardless
    return "prompting"

print(choose_approach({
    "knowledge_changes_frequently": True,
    "needs_source_citation": True,
    "needs_consistent_narrow_behavior_at_scale": False,
    "has_large_labeled_dataset": False,
}))   # 'rag'

print(choose_approach({
    "knowledge_changes_frequently": False,
    "needs_source_citation": False,
    "needs_consistent_narrow_behavior_at_scale": True,
    "has_large_labeled_dataset": True,
}))   # 'fine-tuning'

